  test("score scenario 3", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-04-05");
    expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
    await ui.setSetting(pg_uma, "floor", "0.50");
    await ui.setSetting(pg_uma, "terms", "7");
    await ui.setSetting(pg_uma, "late-pct", "5.00");
    await ui.setSetting(pg_uma, "policy-date", "2026-03-05");
    await ui.setSetting(pg_uma, "terms-C", "20");
    await ui.setSetting(pg_uma, "cap", "5.00");
    await ui.setSetting(pg_uma, "proof-threshold", "1.00");
    await ui.loadSheet(pg_uma, `${sheet}-p`);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "20.00"})).toBe(true);
    const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A"}));
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C"}));
    const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "10.35"}));
    expect(await ui.claimAction(pg_uma, c_cam_0, "open")).toBe(true);
    await ui.loadSheet(pg_uma, sheet);
    await ui.setSetting(pg_uma, "parent", `${sheet}-p`);
    expect(await ui.saveTemplate(pg_uma, {"name": "T1", "amount": "3.33", "note": "tpl"})).toBe(true);
    expect(await ui.setSettingDated(pg_uma, "rounding", "half-up", "2026-03-01", "half-up")).toBe(true);
    expect(await ui.setRole(pg_uma, "wes", "restricted")).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C", "terms": "20", "contact": " Ada@x ", "tags": "c"}));
    expect(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B"})).toBeNull();
    expect(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A"})).toBeNull();
    const pg_wes = await ui.userPage(browser, "wes", sheet);
    await ui.setToday(pg_wes, "2026-04-22");
    await ui.showRetired(pg_wes, true);
    expect(await ui.dups(pg_wes)).toEqual([]);
    const c_dot_0 = ui.must(await ui.quickAdd(pg_wes, {"name": "Dot", "amount": "99.95"}));
    const p_dot = await ui.personId(pg_wes, "Dot");
    await ui.showRetired(pg_wes, true);
    await ui.showRetired(pg_wes, true);
    refused: Number(await shown(page.getByTestId('bulk-reassign-refused'))),
  };
}

export async function bulkSettle(page: Page, claimIds: string[]): Promise<{ settled: number; refused: number }> {
  for (const id of claimIds) await claimRow(page, id).getByTestId('claim-select').setChecked(true);
  await page.getByTestId('bulk-settle').click();
  await expect(page.getByTestId('bulk-settled')).toBeVisible({ timeout: WAIT });
  return {
    settled: Number(await shown(page.getByTestId('bulk-settled'))),
    refused: Number(await shown(page.getByTestId('bulk-settle-refused'))),
  };
}

/** The quick-add bar: the new claim's id, or null when refused. */
/** Quick-add a claim by typed name: the new claim's id, or null when refused. `personId` names
 *  the row the claim lands on when the typed text is not the name that row shows, an alias;
 *  without it the row is found by the typed name. */
export async function quickAdd(page: Page, f: { name: string; amount: string }, personId?: string): Promise<string | null> {
  const before = await ids(claimRows(page), 'claim-row-');
  await page.getByTestId('quick-name').fill(f.name);
  await page.getByTestId('quick-amount').fill(f.amount);
  await page.getByTestId('quick-submit').click();
  const scope = personId !== undefined ? row(page, personId) : rowsNamed(page, f.name);
  let added: string | null = null;
  const ok = await until(page, async () => (added = await addedClaim(scope, before, { amount: f.amount })) !== null,
    page.getByTestId('quick-error'), 'quick add');
  return ok ? added : null;
}

// ---- rates, periods, settings, roles, export -------------------------------------------------

